window.V.data.magic=[{id:"m-muscle",name:"Muscle",kind:"No magic",users:["mash"],arc:"s1",color:"#f3d38a",bio:"Not magic at all. Mash answers every spell with trained strength, speed and endurance."},{id:"m-swap",name:"Swap magic",kind:"Student magic",users:["finn"],arc:"s1",color:"#9fd0ff",bio:"Finn swaps the positions of people and objects."},{id:"m-gravity",name:"Gravity magic",kind:"Student magic",users:["lance"],arc:"s1",color:"#c9a3ff",bio:"Lance increases the gravity on his target, pinning or crushing it."},{id:"m-explosion",name:"Explosion magic",kind:"Student magic",users:["dot"],arc:"s1",color:"#ff8a65",bio:"Dot's magic sets off explosions, fitting his temper. The cross on his forehead, Ira Kreuz, raises its power."},{id:"m-binding",name:"Binding magic",kind:"Student magic",users:["lemon"],arc:"s1",color:"#fff176",bio:"Lemon summons restraints: cuffs, chains and manacles."},{id:"m-iron",name:"Iron magic",kind:"Student magic",users:["silva"],arc:"s1",color:"#b0bec5",bio:"Silva's iron magic, the centre of his challenge to Mash."},{id:"m-size",name:"Size magic",kind:"Student magic",users:["max"],arc:"exam",color:"#ffcc80",bio:"Max Land changes how big an object is."},{id:"m-sound",name:"Sound magic",kind:"Student magic",users:["margarette"],arc:"exam",color:"#f48fb1",bio:"Margarette fights by controlling sound."},{id:"m-pain",name:"Pain-transfer magic",kind:"Student magic",users:["carpaccio"],arc:"exam",color:"#80cbc4",bio:"Carpaccio's Master Cane magic: a goddess statue takes his wounds, so he feels no pain, and the damage is passed to his enemy. Breaking the statue breaks the spell."},{id:"m-doll",name:"Puppet magic",kind:"Magia Lupus magic",users:["abel"],arc:"lupus",color:"#9575cd",bio:"Abel Walker turns people into puppets and dolls and controls them."},{id:"m-evil-eye",name:"Evil Eye",kind:"Magia Lupus magic",users:["abyss"],arc:"lupus",color:"#7e57c2",bio:"The rare eye Abyss Razor was born with. It can briefly cancel other people's magic, and people feared and shunned him for it."},{id:"m-mud",name:"Mud magic",kind:"Magia Lupus magic",users:["wirth"],arc:"lupus",color:"#8d6e63",bio:"Wirth Madl's mud magic."},{id:"m-tornado",name:"Tornado magic",kind:"Magia Lupus magic",users:["love"],arc:"lupus",color:"#f06292",bio:"Love Cute summons tornadoes."},{id:"m-shark",name:"Underwater magic",kind:"Magia Lupus magic",users:["olore"],arc:"lupus",color:"#4fc3f7",bio:"Olore Andrew makes an underwater space and turns into a shark to fight inside it."},{id:"m-sword",name:"Sword magic",kind:"Divine Visionary cane",users:["rayne"],arc:"s1",color:"#90caf9",bio:"Rayne Ames, holder of the Sword Cane, creates and controls swords."},{id:"m-sand",name:"Sand magic",kind:"Divine Visionary cane",users:["orter"],arc:"exam",color:"#e0b26b",bio:"The Desert Cane's holder, Orter Madl, controls sand."},{id:"m-lights",name:"Light magic",kind:"Divine Visionary cane",users:["ryoh"],arc:"exam",color:"#fff6c2",bio:"Ryoh Grantz's beams of light can cut through almost anything."},{id:"m-flame",name:"Flame magic",kind:"Divine Visionary cane",users:["kaldo"],arc:"exam",color:"#ff7043",bio:"Kaldo Gehenna, holder of the Flame Cane, controls fire, including a sword of black flame."},{id:"m-dragon",name:"Dragon magic",kind:"Divine Visionary cane",users:["agito"],arc:"exam",color:"#81c784",bio:"Agito Tyrone, holder of the Dragon Cane, commands his pet dragon and can turn it into a much larger form."},{id:"m-ice",name:"Ice magic",kind:"Divine Visionary cane",users:["tsurara"],arc:"exam",color:"#b3e5fc",bio:"Tsurara Halestone, holder of the Ice Cane, can freeze anything."},{id:"m-immortal",name:"Undead magic",kind:"Divine Visionary cane",users:["renatus"],arc:"exam",color:"#ce93d8",bio:"Renatus Revol, holder of the Immortal Cane, summons the body parts of the undead. He cannot die."},{id:"m-knowledge",name:"Word magic",kind:"Divine Visionary cane",users:["sophina"],arc:"exam",color:"#a1887f",bio:"Sophina Biblia, holder of the Knowledge Cane, controls words and through them what her targets do."},{id:"m-space",name:"Space magic",kind:"Great mages",users:["wahlberg"],arc:"s1",color:"#d1c4e9",bio:"Headmaster Wahlberg Baigan controls space itself. During the attack on Easton Innocent Zero manages to steal it."},{id:"m-darkness",name:"Darkness magic",kind:"Great mages",users:["adam"],arc:"attack",color:"#90a4ae",canon:"check",bio:"Adam Jobs' magic of darkness, which erases its target from existence."},{id:"m-time",name:"Time magic",kind:"Great mages",users:["innocent-zero"],arc:"attack",color:"#ef5350",bio:"Innocent Zero stops, speeds up and turns back time: he freezes the exam audience, ages half of Wahlberg's body and rewinds time to undo Wahlberg's spell. He can also change his appearance."},{id:"m-carbon",name:"Carbon magic",kind:"Innocent Zero's side",users:["cell"],arc:"lupus",color:"#e1bee7",bio:"Cell War controls carbon and turns it into diamond."},{id:"m-baby",name:"Baby magic",kind:"Innocent Zero's side",users:["sitter-baby"],arc:"attack",color:"#ffab91",bio:"The Criminal Cane Sitter Baby turns people, or the user, into babies."},{id:"m-mirror",name:"Mirror magic",kind:"Innocent Zero's side",users:["doom"],arc:"final",sp:"m",color:"#b71c1c",bio:"Doom copies his enemy's movements and creates mirror duplicates."},{id:"m-invisible",name:"Invisibility magic",kind:"Innocent Zero's side",users:["famin"],arc:"final",sp:"m",color:"#c62828",bio:"Famin turns things invisible and fights with playing cards."},{id:"m-orichalcum",name:"Orichalcum magic",kind:"Innocent Zero's side",users:["epidem"],arc:"final",sp:"m",color:"#d84315",bio:"Epidem creates and controls orichalcum."},{id:"m-guandao",name:"Guandao magic",kind:"Innocent Zero's side",users:["delisaster"],arc:"final",sp:"m",color:"#e53935",bio:"Delisaster creates and controls guandao polearms."},{id:"m-water",name:"Water magic",kind:"Innocent Zero's side",users:["domina"],arc:"tma",sp:"m",color:"#4dd0e1",bio:"Domina, Walkis' top student, controls water."},{id:"m-magnet",name:"Magnetism magic",kind:"Walkis magic",users:["levis"],arc:"tma",sp:"m",color:"#ffd54f",bio:"Lévis Rosequartz controls magnetism and electricity."}];window.V.data.creatures=[{id:"hyperion",name:"Hyperion",kind:"Summon",users:["ryoh"],arc:"exam",first:"Season 2",color:"#fff6c2",canon:"check",bio:"A being Ryoh Grantz is said to summon with his light magic. This entry still needs checking against the source."},{id:"agito-dragon",name:"Agito's dragon",kind:"Dragon",users:["agito"],arc:"exam",first:"Season 2",color:"#81c784",canon:"check",bio:"The pet dragon Agito Tyrone fights through. He can turn it into a much larger form."},{id:"minotaur",name:"Minotaurs",kind:"Exam beast",arc:"exam",first:"Season 2, episode 16",color:"#a1887f",bio:"Magic-immune minotaurs that roam the first stage of the Divine Visionary Selection Exam while the candidates hunt for keys."},{id:"magiparasite",name:"Magiparasite",kind:"Parasite",arc:"exam",first:"Season 2, episode 13",color:"#aed581",bio:"A parasite Mash pulls out of the judge, Mr. Bless, during the Bureau of Magic's hearing on him."}];window.V.data.orgs=[{id:"h-easton",name:"Easton Magic Academy",short:"Easton",kind:"School",lead:["wahlberg"],color:"#5aa9ff",known:"Where Divine Visionaries are made",note:"The prestigious magic school Mash enrols in, headed by Wahlberg Baigan. Students are sorted into three houses: Adler, Lang and Orca. Its best students can become Divine Visionary candidates."},{id:"h-adler",name:"Adler House",short:"Adler",kind:"House",lead:["rayne"],color:"#f3d38a",known:"Mash's house",note:"The Easton house of Mash, Finn, Lance, Dot and Lemon. Rayne Ames is its prefect."},{id:"h-lang",name:"Lang House",short:"Lang",kind:"House",lead:["abel"],color:"#9575cd",known:"Home of Magia Lupus",note:"The Easton house whose prefect, Abel Walker, secretly leads Magia Lupus. Mash and his friends raid the Lang dormitory in Season 1."},{id:"h-orca",name:"Orca House",short:"Orca",kind:"House",lead:["margarette"],color:"#f48fb1",known:"Margarette's house",note:"The Easton house led by its prefect, Margarette Macaron. Carpaccio Luo-Yang is one of its first-years."},{id:"h-visionaries",name:"Divine Visionaries",short:"Visionaries",kind:"Magic Bureau",color:"#f3d38a",known:"The eight canes",note:"The highest mages of the Bureau of Magic, each heading part of it. Each holds a cane named for their magic: Sword, Desert, Light, Flame, Dragon, Ice, Immortal and Knowledge."},{id:"h-magia-lupus",name:"Magia Lupus",short:"Lupus",kind:"Antagonist group",lead:["abel"],color:"#7e57c2",known:"Ranking people by talent",note:"A secret group in Lang House led by Abel Walker. Its members are numbered as Fangs, and they believe the gifted should rule over the rest."},{id:"h-zero-family",name:"Innocent Zero's family",short:"Zero",kind:"Antagonist group",lead:["innocent-zero"],color:"#ef5350",known:"Innocent Zero and his six sons",note:"Innocent Zero fathered six sons, Mash the youngest, and plans to take their hearts to become immortal."},{id:"h-criminal-canes",name:"Criminal Canes",short:"Criminal",kind:"Antagonist group",lead:["innocent-zero"],color:"#ff8a65",known:"Freed death-row prisoners",note:"Former death-row prisoners who fight for Innocent Zero. Sitter Baby is one of them."},{id:"h-walkis",name:"Walkis Magic Academy",short:"Walkis",kind:"School",sp:"m",color:"#4dd0e1",known:"Power is everything",note:"One of the top three magic schools, which believes power is everything. Its students meet Easton's in the Tri-Magic-Athalon."}];window.V.data.arcs=[{id:"pre",label:"Before Easton",short:"Mash's childhood",note:"Raised in secret in the forest."},{id:"s1",label:"Easton Magic Academy",short:"Season 1",note:"Mash enrols, makes friends and earns coins."},{id:"lupus",label:"Magia Lupus",short:"Season 1",note:"The raid on Lang House and the fight with Abel Walker."},{id:"exam",label:"Divine Visionary Selection Exam",short:"Season 2",note:"The hearing, the Divine Visionaries and the exam stages."},{id:"attack",label:"Innocent Zero's attack",short:"Season 2",note:"Innocent Zero strikes the exam and Mash learns who his father is."},{id:"tma",label:"Tri-Magic-Athalon",short:"Manga",sp:"m"},{id:"final",label:"Final battle",short:"Manga",sp:"m"}];window.V.data.links=[{a:"regro",b:"mash",t:"family",label:"Adoptive son",labelB:"Adoptive father"},{a:"rayne",b:"finn",t:"family",label:"Younger brother",labelB:"Elder brother"},{a:"lance",b:"anna",t:"family",label:"Younger sister",labelB:"Elder brother"},{a:"orter",b:"wirth",t:"family",label:"Younger brother",labelB:"Elder brother"},{a:"wahlberg",b:"mash",t:"mentor",label:"Student he protects",labelB:"Headmaster who believes in him"},{a:"adam",b:"wahlberg",t:"mentor",label:"His pupil",labelB:"His teacher"},{a:"adam",b:"innocent-zero",t:"mentor",label:"His pupil",labelB:"His teacher",canon:"check"},{a:"mash",b:"finn",t:"bond",label:"Roommate and best friend",labelB:"Roommate and best friend"},{a:"mash",b:"lance",t:"bond",label:"Friend and rival",labelB:"Friend and true rival"},{a:"mash",b:"dot",t:"bond",label:"Friend and self-proclaimed rival",labelB:"Friend"},{a:"mash",b:"lemon",t:"bond",label:"Self-declared fiancée",labelB:"The boy she loves"},{a:"finn",b:"lance",t:"bond",label:"Housemate"},{a:"finn",b:"dot",t:"bond",label:"Housemate"},{a:"mash",b:"abyss",t:"bond",label:"Friend",labelB:"The one who saw him as a person"},{a:"abel",b:"abyss",t:"bond",label:"Best friend",labelB:"Best friend"},{a:"rayne",b:"mash",t:"ally",label:"Student he comes to respect",labelB:"Divine Visionary who protects him"},{a:"tom",b:"mash",t:"ally",label:"His Duelo recruit",labelB:"Recruited him for Duelo"},{a:"max",b:"mash",t:"ally",label:"Teamed up in the exam"},{a:"brad",b:"mash",t:"ally",label:"The boy he found out",labelB:"Police officer who found him out, then helped him enrol"},{a:"ryoh",b:"mash",t:"ally",label:"Student he sides with",labelB:"Divine Visionary on his side"},{a:"ryoh",b:"rayne",t:"ally",label:"Fellow Divine Visionary"},{a:"orter",b:"rayne",t:"ally",label:"Fellow Divine Visionary"},{a:"orter",b:"margarette",t:"ally",label:"Sent to stop Mash",labelB:"Gave the order"},{a:"cell",b:"innocent-zero",t:"ally",label:"His creator and master",labelB:"Clone who serves him"},{a:"lance",b:"dot",t:"rival",label:"Bickering rival"},{a:"orter",b:"mash",t:"rival",label:"Wants him removed",labelB:"Opposes him"},{a:"kaldo",b:"mash",t:"rival",label:"Pointing game ended in a draw"},{a:"margarette",b:"mash",t:"rival",label:"Duelled in the exam"},{a:"carpaccio",b:"finn",t:"rival",label:"Will stronger than his own",labelB:"Captured and wounded him"},{a:"innocent-zero",b:"mash",t:"enemy",label:"Son whose heart he wants",labelB:"Father who wants his heart"},{a:"innocent-zero",b:"wahlberg",t:"enemy",label:"Fought him at the exam"},{a:"mash",b:"abel",t:"enemy",label:"Defeated him",labelB:"Defeated by"},{a:"lance",b:"wirth",t:"enemy",label:"Defeated him",labelB:"Defeated by"},{a:"dot",b:"love",t:"enemy",label:"Fought her",labelB:"Fought him",canon:"check"},{a:"mash",b:"olore",t:"enemy",label:"Defeated him underwater",labelB:"Defeated by"},{a:"mash",b:"silva",t:"rival",label:"Beat him, then freed him",labelB:"Challenged him"},{a:"mash",b:"cell",t:"enemy",label:"Defeated him twice",labelB:"Defeated by"},{a:"cell",b:"abel",t:"enemy",label:"Sent to kill him",labelB:"Came to kill him"},{a:"mash",b:"carpaccio",t:"enemy",label:"Defeated him",labelB:"Defeated by"},{a:"rayne",b:"margarette",t:"enemy",label:"Defeated",labelB:"Stopped by"},{a:"lance",b:"sitter-baby",t:"enemy",label:"Defeated",labelB:"Defeated by"},{a:"wahlberg",b:"adam",t:"enemy",label:"Defeated his revived body",labelB:"Pupil who defeated his revived body"},{a:"mash",b:"domina",t:"family",label:"Brother",sp:"m"},{a:"mash",b:"doom",t:"enemy",label:"Eldest brother",labelB:"Youngest brother",sp:"m"},{a:"ryoh",b:"domina",t:"ally",label:"Saved him",labelB:"Saved by",sp:"m"},{a:"domina",b:"mash",t:"bond",label:"Brother he sacrificed himself for",labelB:"Brother who sacrificed himself for him",sp:"m"},{a:"lance",b:"epidem",t:"enemy",label:"Defeated with Dot",labelB:"Defeated by",sp:"m"},{a:"dot",b:"epidem",t:"enemy",label:"Defeated with Lance",labelB:"Defeated by",sp:"m"}];window.V.data.timeline=[{id:"t-forest",arc:"pre",when:"Mash's childhood",kind:"event",title:"Found in the forest",ids:["regro","mash"],text:"Regro Burnedead takes in a baby born without magic and raises him in secret, because a child without magic would be eliminated."},{id:"t-discovered",arc:"s1",when:"Season 1, ep. 1",kind:"event",title:"Discovered",ids:["mash","regro","brad"],text:"A police officer, Brad Coleman, finds out Mash has no magic. To protect Regro, Mash agrees to enrol at Easton and aim to become a Divine Visionary."},{id:"t-enrol",arc:"s1",when:"Season 1, ep. 2",kind:"event",title:"Entering Easton",ids:["mash","finn","lemon","wahlberg"],text:"Mash passes the entrance exam by smashing through the walls of the maze, saves Lemon and is placed in Adler House with Finn."},{id:"t-duelo",arc:"s1",when:"Season 1, ep. 3-4",kind:"battle",title:"Duelo and Lance",ids:["mash","tom","lance"],text:"Tom Knowles recruits Mash for the Duelo team, where he scores 999 points. Mash then duels Lance, who is moved by Mash's loyalty to his friends."},{id:"t-silva",arc:"s1",when:"Season 1, ep. 5-6",kind:"battle",title:"The iron challenge",ids:["mash","dot","silva"],text:"Students are sorted into dormitories. After Silva beats Dot and spoils Mash's cream puff, Mash takes his challenge and wins."},{id:"t-lupus",arc:"lupus",when:"Season 1, ep. 6-7",kind:"event",title:"Magia Lupus",ids:["abel","mash","olore","silva"],text:"Lance warns Mash about Lang's secret leaders, Magia Lupus. Abel turns students into dolls; Mash frees Silva and beats Olore underwater."},{id:"t-raid",arc:"lupus",when:"Season 1, ep. 8-9",kind:"battle",title:"Raid on Lang",ids:["mash","lance","wirth","abyss"],text:"Mash and his friends raid the Lang dormitory. Lance defeats Wirth Madl, and Mash defeats Abyss, who becomes his friend."},{id:"t-abel",arc:"lupus",when:"Season 1, ep. 10-11",kind:"battle",title:"Mash against Abel",ids:["dot","love","rayne","mash","abel"],text:"Dot unlocks his Ira Kreuz, Rayne Ames helps Mash reach Abel, and Mash defeats him. Abel surrenders and frees the students he turned into dolls."},{id:"t-mirror",arc:"lupus",when:"Season 1, ep. 12",kind:"reveal",title:"The magic mirror",ids:["cell","abel","mash"],text:"Innocent Zero's agent Cell War comes to kill Abel. Mash smashes his mirror, and the truth comes out: Mash has only ever used his muscles."},{id:"t-hearing",arc:"exam",when:"Season 2, ep. 13",kind:"event",title:"The hearing",ids:["mash","wahlberg","rayne","orter","ryoh","kaldo","agito","tsurara","renatus","sophina"],text:"The Bureau of Magic summons Mash, and the Divine Visionaries argue over executing him. Mash pulls a Magiparasite out of the judge, and Wahlberg speaks for him. He may live if he becomes a Divine Visionary."},{id:"t-margarette",arc:"exam",when:"Season 2, ep. 14-15",kind:"battle",title:"Rayne against Margarette",ids:["orter","margarette","rayne","mash"],text:"Orter Madl sends Margarette Macaron to stop Mash before the exam. Rayne Ames steps in and defeats Margarette."},{id:"t-exam",arc:"exam",when:"Season 2, ep. 15-16",kind:"event",title:"The Divine Visionary Selection Exam",ids:["mash","max","dot","finn","lance","wahlberg"],text:"Wahlberg explains the gulf between two-line and three-line mages, and the exam begins. Candidates hunt keys among magic-immune minotaurs, then smash crystals in the second stage."},{id:"t-carpaccio",arc:"exam",when:"Season 2, ep. 17",kind:"battle",title:"Finn's will",ids:["finn","carpaccio","mash"],text:"Carpaccio, holder of a Master Cane, captures and wounds Finn. Mash shatters his goddess statue and defeats him, and Carpaccio sees that Finn's will is stronger than his own."},{id:"t-duel",arc:"exam",when:"Season 2, ep. 18-19",kind:"battle",title:"Mash against Margarette",ids:["mash","kaldo","margarette"],text:"Mash survives Kaldo Gehenna's deadly pointing game, then defeats Margarette's sound magic in the third-stage duel."},{id:"t-attack",arc:"attack",when:"Season 2, ep. 20",kind:"battle",title:"Innocent Zero strikes",ids:["innocent-zero","wahlberg","mash","cell","lance","sitter-baby"],text:"Innocent Zero freezes the audience with time magic. Wahlberg frees Mash and his friends to fight back: Mash defeats Cell War and Lance defeats Sitter Baby."},{id:"t-son",arc:"attack",when:"Season 2, ep. 21",kind:"reveal",title:"Adam's legacy and Innocent's plan",ids:["adam","wahlberg","innocent-zero","cell","mash"],text:"Innocent Zero revives the body of Adam Jobs, and Wahlberg defeats it. Cell reveals Innocent's plan to take his sons' hearts for immortality. Mash is one of those sons."},{id:"t-wahlberg",arc:"attack",when:"Season 2, ep. 22",kind:"battle",title:"Wahlberg against Innocent Zero",ids:["wahlberg","innocent-zero","mash"],text:"Innocent Zero ages half of Wahlberg's body and turns back time to undo his strongest spell, until Mash arrives and kicks Innocent in the face."},{id:"t-monster",arc:"attack",when:"Season 2, ep. 23",kind:"battle",title:"The giant monster",ids:["mash","innocent-zero"],text:"Innocent Zero fights Mash hand to hand and fuses his fallen demons into a giant monster. Mash drags it away from the arena to the mountains, and the students cheer him."},{id:"t-aftermath",arc:"attack",when:"Season 2, ep. 24",kind:"event",title:"Aftermath",ids:["mash","finn","wahlberg"],text:"The Bureau covers up what happened. Finn talks Mash into carrying on, Mash passes his exams and promises to become a Divine Visionary, and Wahlberg warns that his friends are now in danger too."},{id:"t-tma",arc:"tma",when:"Manga",kind:"event",title:"Tri-Magic-Athalon",ids:["mash","domina","levis"],sp:"m",text:"The Divine Visionary final exam pits Easton against other top schools, including Walkis Magic Academy. Mash meets Domina, another of Innocent Zero's sons."},{id:"t-domina",arc:"tma",when:"Manga",kind:"reveal",title:"Domina's sacrifice",ids:["domina","mash","ryoh"],sp:"m",text:"Domina sides with Mash and sacrifices himself for him. Ryoh Grantz saves him."},{id:"t-brothers",arc:"final",when:"Manga",kind:"battle",title:"Mash's brothers",ids:["doom","famin","epidem","delisaster","lance","dot"],sp:"m",text:"Innocent Zero's elder sons move against the magic world. Lance and Dot defeat Epidem together."},{id:"t-final",arc:"final",when:"Manga",kind:"battle",title:"Mash against Innocent Zero",ids:["mash","innocent-zero","wahlberg"],sp:"m",text:"The final battle against Innocent Zero."}];
